bool ScriptSession::unitSelectable(std::uint32_t handle) {return alive(handle,NativeKind::Unit) && !units_.at(handle)->removing && !units_.at(handle)->concoction && !units_.at(handle)->swarmAgent && !capability(*units_.at(handle),"Aloc");}
bool ScriptSession::idleWorker(std::uint32_t handle,unsigned player) {
    if(!unitSelectable(handle))return false;auto& u=*units_.at(handle);auto& combat=u.combat;
    if(u.owner!=player || u.removing || u.hidden() || u.paused || u.illusion || u.building || number(u.life)<=0 || definitions().unitClasses(u.type).find("peon")==std::string::npos)return false;
    return !u.currentOrder && u.route.empty() && u.gather.phase==GatherOrder::Phase::None && !u.buildOrder && !u.workingOn && !u.repair && !u.cast && !combat.target && !combat.follow && !combat.pickup && !combat.board && !combat.attackMove && !combat.patrolStart && !combat.patrolEnd && !combat.itemMove && !combat.returning && !combat.windup;
}
bool ScriptSession::setPlayerUnitSelected(unsigned player,std::uint32_t handle,bool selected) {if(player>=16 || !alive(handle,NativeKind::Unit) || units_.at(handle)->removing || (selected && !unitSelectable(handle)))return false;if(localPlayer_ && *localPlayer_==player)syncLocalSelection();auto& selection=synchronizedSelections_[player];bool wasSelected=selection.contains(handle);if(wasSelected==selected)return true;if(selected)selection.insert(handle);else selection.erase(handle);if(localPlayer_ && *localPlayer_==player)units_.at(handle)->selected=selected;auto revision=++selectionRevisions_[player][handle];selectionEvent(handle,player,selected,revision);return true;}
void ScriptSession::selectUnit(std::uint32_t handle,bool selected) {if(localPlayer_){setPlayerUnitSelected(*localPlayer_,handle,selected);return;}auto& u=unit(runtime_.handle("unit",handle));if(u.selected==selected || (selected && !unitSelectable(handle)))return;u.selected=selected;unitEvent(handle,selected?24:25,selected?57:58);}
bool ScriptSession::stopUnit(std::uint32_t handle,bool hold) {auto& u=unit(runtime_.handle("unit",handle));if(u.paused || u.stunned() || u.unsummon || u.hidden() || number(u.life)<=0)return false;if(!cancelCombat(u))return false;u.route.clear();u.waypoint=0;u.currentOrder=hold?851993:851972;u.holding=hold;u.animationStart=simulationTime_;u.animationTime=0;u.animation.clear();u.animationIndex.reset();u.animationQueue.clear();ScriptContext context;context.issuedOrder=u.currentOrder;auto revision=u.combat.revision;unitEvent(handle,38,75,context);if(!hold && alive(handle,NativeKind::Unit) && u.combat.revision==revision && u.currentOrder==851972)u.currentOrder=0;return true;}
bool ScriptSession::moveUnit(std::uint32_t handle,WorldPoint target,std::uint32_t order,std::optional<WorldPoint> destination) {
    if(!alive(handle,NativeKind::Unit))return false;if(castPointOrder(handle,order,target))return true;if(!alive(handle,NativeKind::Unit))return false;if(alive(handle,NativeKind::Unit) && std::find(units_.at(handle)->buildables.begin(),units_.at(handle)->buildables.end(),order)!=units_.at(handle)->buildables.end())return build(handle,order,target);if(order==851983 || order==851990)return attackMove(handle,target,order==851990,destination);auto& u=unit(runtime_.handle("unit",handle));if(order==851980 || (order==851971 && (u.stationaryBuilding() || factories_.contains(handle))))return setRally(handle,target);if((order!=851986 && order!=851971) || u.paused || u.stunned() || u.hidden() || u.stationaryBuilding() || u.rooted() || number(u.life)<=0 || number(u.currentMoveSpeed())<=0)return false;target=requireWorld().clamp(target);auto end=destination?requireWorld().clamp(*destination):target;auto route=u.pathing?requireWorld().route({u.x,u.y},end,u.collision,pathMovement(u.movementType)):std::vector<WorldPoint>{end};if(route.empty())return false;if(!cancelCombat(u))return false;u.route=std::move(route);u.waypoint=0;u.pathingRevision=requireWorld().blockingRevision();u.currentOrder=order;u.holding=false;u.animationStart=simulationTime_;u.animationTime=0;u.animation.clear();u.animationIndex.reset();u.animationQueue.clear();ScriptContext context;context.issuedOrder=order;context.orderPoint=target;unitEvent(handle,39,76,context);return true;
}
void ScriptSession::moveUnits(double delta) {
    for(auto& [handle,state]:units_){auto& u=*state;if(u.timedFacing){auto& turn=*u.timedFacing;turn.elapsed=std::min(turn.duration,turn.elapsed+delta);u.facing=real(std::fmod(std::fmod(turn.start+turn.delta*float(turn.elapsed/turn.duration),360.f)+360.f,360.f));if(turn.elapsed>=turn.duration)u.timedFacing.reset();}if(!u.paused){if(!(u.corpse && (u.transport || (u.decaySuspended && u.corpse->elapsed>=u.corpse->death)))){u.animationTime+=delta*u.animationRate*(u.animation=="Attack"?u.combat.animationSpeed:1);updateUnitAnimation(u);}auto difference=u.targetFlyHeight-u.flyHeight;auto step=float(delta)*u.flyRate;if(step>0)u.flyHeight+=std::clamp(difference,-step,step);updateGrounding(u,delta);}if(u.swarmAgent || u.paused || u.phaseShifted() || u.stunned() || u.rooted() || u.waypoint>=u.route.size() || number(u.life)<=0)continue;if(u.pathing && u.pathingRevision!=requireWorld().blockingRevision()){auto goal=u.route.back();u.route=requireWorld().route({u.x,u.y},goal,u.collision,pathMovement(u.movementType));u.waypoint=0;u.pathingRevision=requireWorld().blockingRevision();if(u.route.empty())continue;}float speed=number(u.currentMoveSpeed())*std::max(0.f,1+u.aura.movement)*u.spellMoveFactor();for(auto& [id,b]:u.buffs)if(b.moveLimit>0)speed=std::min(speed,b.moveLimit);float remaining=float(delta)*speed;while(remaining>0 && u.waypoint<u.route.size()){auto target=u.route[u.waypoint];float x=number(u.x),y=number(u.y),dx=number(target.x)-x,dy=number(target.y)-y,distance=std::hypot(dx,dy);if(distance>.001f){u.timedFacing.reset();u.facing=real(std::fmod(std::atan2(dy,dx)*180.f/3.14159265359f+360.f,360.f));}if(distance<=remaining){u.x=target.x;u.y=target.y;remaining-=distance;++u.waypoint;}else{u.x=real(x+dx/distance*remaining);u.y=real(y+dy/distance*remaining);remaining=0;}}if(u.waypoint>=u.route.size()){u.route.clear();u.waypoint=0;if(!u.combat.target && !u.combat.attackMove && !u.combat.follow && !u.combat.pickup && !u.combat.itemMove && !u.combat.returning && u.gather.phase==GatherOrder::Phase::None && !u.cast && !u.buildOrder && !u.repair && !u.workingOn)u.currentOrder=0;u.animationStart=simulationTime_;u.animationTime=0;u.animation.clear();u.animationIndex.reset();u.animationQueue.clear();}}
}
void ScriptSession::bindOrderNatives() {
    auto point=[](jass::Value x,jass::Value y){return WorldPoint{jass::Real::fromBits(x.bits),jass::Real::fromBits(y.bits)};};auto id=[](const jass::Value& v){if(!v.text)return 0u;auto known=orderId(*v.text);return known?known:v.text->size()==4?ObjectData::code(*v.text):0u;};
    bind("IssuePointOrder","boolean",{"unit","string","real","real"},[this,point,id](auto& vm,auto a){return vm.boolean(moveUnit(a[0].bits,point(a[2],a[3]),id(a[1])));});
    bind("IssuePointOrderById","boolean",{"unit","integer","real","real"},[this,point](auto& vm,auto a){return vm.boolean(moveUnit(a[0].bits,point(a[2],a[3]),a[1].bits));});
    bind("IssuePointOrderLoc","boolean",{"unit","string","location"},[this,id](auto& vm,auto a){auto p=std::get<WorldPoint>(object(a[2],NativeKind::Location).state);return vm.boolean(moveUnit(a[0].bits,p,id(a[1])));});
    bind("IssuePointOrderByIdLoc","boolean",{"unit","integer","location"},[this](auto& vm,auto a){auto p=std::get<WorldPoint>(object(a[2],NativeKind::Location).state);return vm.boolean(moveUnit(a[0].bits,p,a[1].bits));});
    bind("IssueImmediateOrderById","boolean",{"unit","integer"},[this](auto& vm,auto a){if(castImmediateOrder(a[0].bits,a[1].bits))return vm.boolean(true);if(a[1].bits==852025 || a[1].bits==852026 || a[1].bits==852162 || a[1].bits==852163 || a[1].bits==852203 || a[1].bits==852204)return vm.boolean(repairAutocast(a[0].bits,a[1].bits==852025 || a[1].bits==852162 || a[1].bits==852203));if(a[1].bits==852020)return vm.boolean(returnResources(a[0].bits));if(a[1].bits==851976)return vm.boolean(cancelBuildingUpgrade(a[0].bits) || cancelConstruction(a[0].bits) || cancelProduction(a[0].bits));if(a[1].bits==851972 || a[1].bits==851993)return vm.boolean(stopUnit(a[0].bits,a[1].bits==851993));if(upgradeBuilding(a[0].bits,a[1].bits))return vm.boolean(true);return vm.boolean(definitions().upgrade(a[1].bits)?research(a[0].bits,a[1].bits):train(a[0].bits,a[1].bits));});
    bind("GetIssuedOrderId","integer",{},[this](auto& vm,auto){return vm.integer(contexts_.empty()?0:std::bit_cast<std::int32_t>(contexts_.back().issuedOrder));});
    bind("GetOrderedUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty() || !contexts_.back().issuedOrder?0:contexts_.back().triggerUnit);});
    bind("GetOrderPointX","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().orderPoint.x);});
    bind("GetOrderPointY","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().orderPoint.y);});
    bind("GetOrderPointLoc","location",{},[this](auto&,auto){auto p=contexts_.empty()?WorldPoint{}:contexts_.back().orderPoint;auto handle=create(NativeKind::Location);std::get<WorldPoint>(object(handle,NativeKind::Location).state)=p;return handle;});
}
